  cfg.topMode = ['theme', 'pear', 'custom'].includes(cfg.topMode) ? cfg.topMode : (cfg.topImage ? 'custom' : 'theme');
  cfg.size = Math.max(32, Math.min(120, Number(cfg.size) || 56));
