  baseStyle.textContent = `
:is(#pw-panel,.pw-dialog) {
  --pw-bg: var(--cw-bg);
  --pw-surface: var(--cw-surface);
  --pw-soft: var(--cw-accent-soft);
  --pw-text: var(--cw-text);
  --pw-dim: var(--cw-text-dim);
  --pw-border: var(--cw-border);
  --pw-accent: var(--cw-accent);
  --pw-danger: var(--cw-danger);
  --pw-radius: var(--cw-radius);
  color: var(--pw-text);
  font: calc(14px * var(--cw-fs, 1))/1.65 -apple-system,"PingFang SC","Microsoft YaHei",sans-serif;
  box-sizing: border-box;
}

:is(#pw-panel,.pw-dialog) *,
:is(#pw-panel,.pw-dialog) *::before,
:is(#pw-panel,.pw-dialog) *::after {
  box-sizing: border-box;
}

#pw-panel {
  position: fixed;
  inset: 0;
  z-index: 2147483646;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  color: var(--pw-text);
  background: var(--pw-bg);
  overflow: hidden;
  backdrop-filter: blur(20px);
}

.pw-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  flex-shrink: 0;
  padding: 12px 16px;
  padding-top: max(12px, env(safe-area-inset-top));
  border-bottom: 1px solid var(--pw-border);
}

.pw-title {
  flex: 1;
  font-size: calc(18px * var(--cw-fs, 1));
  font-weight: 650;
}

.pw-body {
  display: flex;
  flex: 1;
  min-height: 0;
  overflow: hidden;
}

.pw-books {
  width: 280px;
  flex-shrink: 0;
  overflow: auto;
  padding: 12px;
  border-right: 1px solid var(--pw-border);
}

.pw-main {
  flex: 1;
  min-width: 0;
  overflow: auto;
  padding: 14px;
}

.pw-book,
.pw-box,
.pw-entry {
  border: 1px solid var(--pw-border);
  border-radius: 0;
  background: var(--pw-surface);
}

.pw-book {
  margin-top: 8px;
  padding: 10px;
}

.pw-book.is-active {
  border-color: var(--pw-accent);
  background: var(--pw-surface);
}

.pw-book-name {
  overflow-wrap: anywhere;
  font-weight: 650;
}

.pw-entry-list {
  margin-top: 12px;
}

.pw-entry {
  margin-bottom: 12px;
  padding: 12px;
}

.pw-entry.is-disabled {
  opacity: .68;
}

.pw-entry-head {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--pw-border);
}

.pw-entry-name {
  flex: 1;
  min-width: 160px;
}

.pw-entry-input {
  width: 100%;
}

.pw-entry-label {
  display: block;
  margin-top: 10px;
  color: var(--pw-dim);
  font-size: calc(12px * var(--cw-fs, 1));
}

.pw-entry-keys {
  width: 100%;
}

.pw-entry-content {
  display: block;
  width: 100%;
  min-height: 170px;
  margin-top: 5px;
  padding: 10px;
  color: var(--pw-text);
  background: transparent;
  border: 1px solid var(--pw-border);
  border-radius: 0;
  font: inherit;
  line-height: 1.8;
  resize: vertical;
}

.pw-entry-content:focus {
  border-color: var(--pw-accent);
}

.pw-button,
.pw-dialog button {
  min-height: 36px;
  padding: 8px 12px;
  color: var(--pw-text);
  background: var(--pw-surface);
  border: 1px solid var(--pw-border);
  border-radius: 0;
  font: inherit;
  cursor: pointer;
}

.pw-button:hover,
.pw-dialog button:hover {
  border-color: var(--pw-accent);
  background: var(--pw-surface);
}

.pw-button:disabled,
.pw-dialog button:disabled {
  opacity: .45;
  cursor: default;
}

.pw-primary {
  color: var(--pw-text);
  background: var(--pw-surface) !important;
  font-weight: 650;
  border-color: var(--pw-accent) !important;
}

.pw-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.pw-row > input[type="text"] {
  flex: 1;
  min-width: 120px;
  width: auto;
}

.pw-field {
  display: block;
  margin-top: 12px;
}

.pw-field > span {
  display: block;
  margin-bottom: 5px;
  color: var(--pw-dim);
}

:is(#pw-panel,.pw-dialog) input,
:is(#pw-panel,.pw-dialog) select,
:is(#pw-panel,.pw-dialog) textarea {
  max-width: 100%;
  padding: 9px;
  color: var(--pw-text);
  background: var(--pw-surface);
  border: 1px solid var(--pw-border);
  border-radius: 0;
  font: inherit;
}

:is(#pw-panel,.pw-dialog) input[type="text"],
:is(#pw-panel,.pw-dialog) select,
:is(#pw-panel,.pw-dialog) textarea {
  width: 100%;
}

:is(#pw-panel,.pw-dialog) textarea {
  resize: vertical;
  line-height: 1.75;
}

:is(#pw-panel,.pw-dialog) select {
  appearance: none;
  padding-right: 30px;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--pw-dim) 50%),
    linear-gradient(135deg, var(--pw-dim) 50%, transparent 50%);
  background-position:
    calc(100% - 15px) 50%,
    calc(100% - 10px) 50%;
  background-size: 5px 5px;
  background-repeat: no-repeat;
}

:is(#pw-panel,.pw-dialog) option {
  color: var(--pw-text);
  background: var(--pw-bg);
}

:is(#pw-panel,.pw-dialog) :is(
  button,
  input,
  textarea,
  select,
  summary
):focus-visible {
  outline: 2px solid var(--pw-accent);
  outline-offset: 2px;
}

.pw-mode {
  width: auto !important;
  min-width: 120px;
}

.pw-entry-title,
.pw-entry-uid {
  color: var(--pw-dim);
  font-size: calc(12px * var(--cw-fs, 1));
}

.pw-note {
  color: var(--pw-dim);
  font-size: calc(12px * var(--cw-fs, 1));
  white-space: pre-wrap;
}

.pw-empty {
  padding: 30px 10px;
  color: var(--pw-dim);
  text-align: center;
}

.pw-box {
  margin-bottom: 12px;
  padding: 12px;
}

.pw-box summary {
  cursor: pointer;
  font-weight: 650;
}

.pw-settings {
  flex-shrink: 0;
  max-height: 55dvh;
  overflow: auto;
  padding: 14px;
  background: var(--pw-surface);
  border-bottom: 1px solid var(--pw-border);
}

.pw-settings[hidden] {
  display: none;
}

.pw-footer {
  flex-shrink: 0;
  padding: 8px 14px;
  padding-bottom: max(8px, env(safe-area-inset-bottom));
  color: var(--pw-dim);
  font-size: calc(12px * var(--cw-fs, 1));
  border-top: 1px solid var(--pw-border);
}

.pw-dialog {
  width: min(460px, calc(100vw - 28px));
  max-height: 85dvh;
  padding: 22px;
  overflow: auto;
  color: var(--pw-text);
  background: var(--pw-bg);
  border: 1px solid var(--pw-border);
  border-radius: 0;
  box-shadow: 0 18px 70px #0008;
}

.pw-dialog::backdrop {
  background: #0007;
  backdrop-filter: blur(4px);
}

.pw-dialog-title {
  margin-bottom: 12px;
  font-size: calc(18px * var(--cw-fs, 1));
  font-weight: 700;
}

.pw-dialog-message {
  margin-bottom: 14px;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

#pw-top {
  display: inline-grid;
  place-items: center;
  align-self: center;
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  margin-left: 14px !important;
  margin-right: 14px !important;
  padding: 3px;
  color: inherit;
  background: transparent;
  border: 0;
  cursor: pointer;
}


#pw-fab {
  position: fixed;
  z-index: 2147483645;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  font-size: calc(32px * var(--cw-fs, 1));
  touch-action: none;
  cursor: grab;
  filter: drop-shadow(0 3px 7px #0005);
}

:is(#pw-top,#pw-fab) img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}

.pw-preview {
  display: grid;
  place-items: center;
  width: 86px;
  height: 86px;
  margin: 10px 0;
  padding: 8px;
  color: var(--pw-text);
  font-size: calc(34px * var(--cw-fs, 1));
  border: 1px solid var(--pw-border);
  background: var(--pw-surface);
}

.pw-preview img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.pw-css-editor {
  min-height: 220px;
  font: calc(13px * var(--cw-fs, 1))/1.65 ui-monospace, Consolas, monospace !important;
}

@media(max-width:680px) {
  .pw-body {
    flex-direction: column;
  }

  .pw-books {
    width: 100%;
    max-height: 30dvh;
    border-right: 0;
    border-bottom: 1px solid var(--pw-border);
  }

  .pw-main {
    padding: 10px;
  }

  .pw-head {
    padding: 10px;
  }

  .pw-entry-name {
    min-width: 140px;
  }
}
`;

