    const DL_ANIMS = [['none', '无'], ['pop', '逐字弹出'], ['fade', '逐字淡入'], ['rise', '逐字上浮'], ['drop', '逐字落下'], ['blur', '逐字变清晰'], ['type', '打字机'], ['wave', '逐字波浪'], ['line', '整句浮现']];
