      d.append(actions(sleep), field('唱片图片', url), actions(button('用这个链接', () => { LM.mc.cover = url.value.trim(); LM.saveMc(); LM.emit(); render(); }), button('上传图片', () => file.click()), button('恢复默认', () => { LM.mc.cover = ''; LM.saveMc(); url.value = ''; LM.emit(); render(); }), file));
